	m = answerFor(t, m, "dev", oneImage("nginx"), false, nil)
	vals := wantHeaderKeys(t, m, "Images", "Refused")
	if vals["Refused"] != "dhi.io, +1" {
		t.Errorf("Refused at 80 columns = %q, want %q", vals["Refused"], "dhi.io, +1")
