)

// DEVDESK-301 (IS-02): level 1 shows what Docker Hub returns (Stars, Official,
// Description) and the Searcher is wired in production.

// catalogServer serves /v2/_catalog with names and counts every request it gets.
func catalogServer(t *testing.T, names ...string) (*httptest.Server, *atomic.Int32) {
	t.Helper()
	var n atomic.Int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		n.Add(1)
		if r.URL.Path != "/v2/_catalog" {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string][]string{"repositories": names})
	}))
	t.Cleanup(srv.Close)
	return srv, &n
}

// TestProductionWiresHubAndCatalogSearchers (DEVDESK-306): the production
// variable is set (TestMain saved it before clearing it for the rest of the
// suite); a private registry is searched through its catalog, no longer
// ErrUnsupported, and dhi.io stays unsupported.
func TestProductionWiresHubAndCatalogSearchers(t *testing.T) {
	if productionImageSearcher == nil {
		t.Fatal("defaultImageSearcher is nil in production: level 1 stays off")
	}
	srv, requests := catalogServer(t, "api", "web")
	imgs, _, err := productionImageSearcher.Search(context.Background(),
		imagesearch.Target{EntryKey: "prod", RegistryURL: "registry.example.com", APIURL: srv.URL},
		imagesearch.Query{Text: "api"})
	if errors.Is(err, imagesearch.ErrUnsupported) {
		t.Fatal("a private registry answered ErrUnsupported: the catalog searcher is not wired")
	}
	if err != nil {
		t.Fatalf("private registry search: %v", err)
	}
	if len(imgs) != 1 || imgs[0].Repo != "api" {
		t.Fatalf("rows = %+v, want the single catalog name api", imgs)
	}
	if requests.Load() == 0 {
}

func (b *blockingSearcher) Search(ctx context.Context, _ imagesearch.Target, _ imagesearch.Query) ([]imagesearch.Image, bool, error) {
	b.started <- ctx
	<-ctx.Done()
	return nil, false, ctx.Err()
}

// withSearchDeadline shrinks imageSearchDeadline and restores it on cleanup.
// Call it before opening the browser.
func withSearchDeadline(t *testing.T, d time.Duration) {
	t.Helper()
	prev := imageSearchDeadline
	imageSearchDeadline = d
	t.Cleanup(func() { imageSearchDeadline = prev })
}

// runCmds runs every Cmd of the lot concurrently and returns the channel their
// messages arrive on.
func runCmds(t *testing.T, cmd tea.Cmd) <-chan ImageSearchResultMsg {
	t.Helper()
	out := make(chan ImageSearchResultMsg, 8)
	for _, c := range flattenBatch(cmd) {
		go func() {
			if r, ok := c().(ImageSearchResultMsg); ok {
				out <- r
			}
		}()
	}
	return out
}

// flattenBatch splits a tea.Batch into its Cmds.
func flattenBatch(cmd tea.Cmd) []tea.Cmd {
	if cmd == nil {
		return nil
	}
	if b, ok := cmd().(tea.BatchMsg); ok {
		return []tea.Cmd(b)
	}
	return nil
}

func recvResult(t *testing.T, ch <-chan ImageSearchResultMsg) ImageSearchResultMsg {
	t.Helper()
	select {
	case r := <-ch:
		return r
	case <-time.After(5 * time.Second):
		t.Fatal("no ImageSearchResultMsg arrived")
	}
	return ImageSearchResultMsg{}
}

// IS-18 c.2: a registry that never answers is cut at the deadline; the result
// carries DeadlineExceeded, adds no row and still counts as answered.
func TestARegistryThatNeverAnswersIsCutAtTheDeadline(t *testing.T) {
	withSearchDeadline(t, 20*time.Millisecond)
	withImageSearcher(t, newBlockingSearcher())

	m, cmd := submitRaw(t, browsingModel(t), "nginx")
	ch := runCmds(t, cmd)
	if m.registryBrowser.pendingSearches != 2 {
		t.Fatalf("pendingSearches = %d, want 2", m.registryBrowser.pendingSearches)
	}
	r := recvResult(t, ch)
func TestAnImageWithNoSavedLaunchOptionsLoadsNothing(t *testing.T) {
	msg := run(t, loadLaunchOptionsCmd("never-launched:v1")).(LaunchOptionsCacheLoadedMsg)

	if msg.Entry != nil {
		t.Errorf("Entry = %+v, want nothing for an image never launched", msg.Entry)
	}
}

// ── helpers ──────────────────────────────────────────────────────────────────

func writeDockerConfig(t *testing.T, cfg map[string]any) {
	t.Helper()
	home, err := os.UserHomeDir()
	if err != nil {
		t.Fatalf("resolving HOME: %v", err)
	}
	dir := filepath.Join(home, ".docker")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatalf("creating %s: %v", dir, err)
	}
	body, err := json.Marshal(cfg)
	if err != nil {
		t.Fatalf("encoding the docker config: %v", err)
	}
	path := filepath.Join(dir, "config.json")
	if err := os.WriteFile(path, body, 0o600); err != nil {
		t.Fatalf("writing %s: %v", path, err)
	}
	t.Cleanup(func() { _ = os.Remove(path) })
}

func encodeAuth(username, password string) string {
	return base64.StdEncoding.EncodeToString([]byte(username + ":" + password))
}
